insert into public.categories (id, slug, name, description, color, icon, "order") values
  ('cat-heritage', 'heritage', 'Heritage & History', 'Palaces, colonial landmarks and living history.', '#f59e0b', 'landmark', 1),
  ('cat-religious', 'religious', 'Sacred Sites', 'Temples, churches and places of worship.', '#fbbf24', 'flame', 2),
  ('cat-nature', 'nature', 'Nature & Gardens', 'Forest reserves, gardens and green escapes.', '#34d399', 'trees', 3),
  ('cat-viewpoint', 'viewpoint', 'Viewpoints', 'Hills, rooftops and the best angles on Kandy.', '#38bdf8', 'mountain', 4),
  ('cat-museum', 'museum', 'Museums', 'Collections that explain Kandy''s story.', '#a78bfa', 'building', 5),
  ('cat-experience', 'experience', 'Experiences', 'Walks, performances and things to do.', '#2dd4bf', 'ticket', 6),
  ('cat-food', 'food', 'Food & Drink', 'Rice and curry, hoppers, cafés and tea.', '#fb7185', 'utensils', 7),
  ('cat-hotel', 'hotel', 'Stay', 'Hotels and guesthouses in and around the city.', '#818cf8', 'bed', 8),
  ('cat-shopping', 'shopping', 'Shopping', 'Markets, malls and local craft.', '#e879f9', 'bag', 9),
  ('cat-transport', 'transport', 'Transport', 'Rail, bus and onward connections.', '#94a3b8', 'train', 10),
  ('cat-health', 'health', 'Health & Safety', 'Hospitals, pharmacies and practical help.', '#f87171', 'cross', 11),
  ('cat-services', 'services', 'Services', 'ATMs, toilets, parking and city services.', '#60a5fa', 'info', 12)
insert into public.places (id, slug, name, category_slug, summary, description, lat, lng, address, website, phone, opening_hours, entry_fee_lkr, estimated_visit_minutes, accessibility, tags, indoor, best_time, practical_notes, verification_status, verification_source, verification_source_url, last_verified_at, location_accuracy, featured, priority) values
  ('plc-temple-tooth', 'temple-of-the-sacred-tooth-relic', 'Temple of the Sacred Tooth Relic', 'religious', 'Sri Lanka''s most sacred Buddhist site and the spiritual heart of Kandy.', 'The Sri Dalada Maligawa houses a tooth relic of the Buddha and sits within the historic royal palace complex beside Kandy Lake. Its whitewashed walls, golden canopy and drumming ceremonies make it the defining image of the city. Visitors should dress conservatively, cover shoulders and knees, and remove shoes before entering the inner shrine.', 7.29365, 80.64129, 'Sri Dalada Veediya, Kandy 20000', 'https://www.sridaladamaligawa.lk/', null, null, null, 75, 'Mostly level courtyard; some thresholds and crowded passages. Confirm step-free access on site.', array['unesco', 'must-see', 'temple', 'culture', 'ceremony']::text[], true, 'Early morning or evening puja', 'Shoulders and knees covered. Shoes removed at the shrine. Photography restrictions vary inside.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 100),
  ('plc-kandy-lake', 'kandy-lake', 'Kandy Lake (Kiri Muhuda)', 'nature', 'A calm artificial lake at the centre of the city, ringed by a shaded walkway.', 'Built in 1807 by King Sri Wickrama Rajasinghe, Kandy Lake — the ''sea of milk'' — anchors the old city. The lake round is a popular early-morning and evening walk, with views to the Temple of the Tooth, the royal palace and the hills above. The central island is a royal bathing pavilion and is not open to the public.', 7.2907, 80.6411, 'Kandy Lake, Kandy 20000', null, null, null, null, 45, 'Paved lakeside path with kerbs and some uneven sections.', array['lake', 'walk', 'sunset', 'free', 'photography']::text[], false, 'Early morning or around sunset', 'The full loop is roughly 3 km. Keep to lit sections after dark.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 98),
  ('plc-bahirawakanda', 'bahirawakanda-buddha-statue', 'Bahirawakanda Vihara Buddha Statue', 'viewpoint', 'A towering white Buddha on a hill with one of the widest views over Kandy.', 'The seated Buddha at Bahirawakanda rises above the city on the western hills, visible from much of Kandy. The temple terrace looks across the lake and the Temple of the Tooth to the Knuckles foothills. It is an active place of worship, so quiet and respectful behaviour is expected.', 7.2873, 80.6301, 'Bahirawakanda, Kandy 20000', null, null, null, null, 40, 'Hillside steps and sloping paths; the terrace is reachable by vehicle but not fully step-free.', array['buddha', 'view', 'sunset', 'temple', 'photography']::text[], false, 'Late afternoon', 'Shoulders and knees covered. A short tuk-tuk ride from the city centre.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 92),
  ('plc-clock-tower', 'kandy-clock-tower', 'Kandy Clock Tower', 'heritage', 'The colonial-era clock tower at the busy junction in front of the railway station.', 'The clock tower is one of central Kandy''s easiest meeting points and a remnant of the city''s colonial civic layout. It stands at the junction of Sri Dalada Veediya and the station approach, surrounded by buses, tuk-tuks and shops. It is a quick stop rather than a long visit.', 7.2934, 80.6367, 'Clock Tower Junction, Kandy 20000', null, null, null, null, 10, 'Street-level, busy traffic, no dedicated viewing area.', array['landmark', 'colonial', 'city-centre', 'free']::text[], false, 'Any time; best photographed in softer light', 'Use pedestrian crossings; traffic is heavy at peak times.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 55),
  ('plc-railway-station', 'kandy-railway-station', 'Kandy Railway Station', 'transport', 'The city''s main rail terminus and the start of the famous hill-country line.', 'Kandy Railway Station connects the city to Colombo and to the scenic line towards Nanu Oya and Ella. The station is central, walkable to the lake and clock tower, and a practical anchor for arrival-day planning. Book reserved seats in advance where possible.', 7.2927, 80.6327, 'Railway Station Road, Kandy 20000', null, null, null, null, 15, 'Platform access involves steps and footbridges; assistance can be arranged with station staff.', array['train', 'arrival', 'transport', 'hill-country']::text[], true, 'Daytime', 'Reserved seats on the Ella line sell out; check current timetables with Sri Lanka Railways.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 70),
  ('plc-city-centre', 'kandy-city-centre', 'Kandy City Centre', 'shopping', 'A modern shopping mall with food, groceries and a practical car park in the city core.', 'Kandy City Centre is the most convenient air-conditioned stop in the centre, with retail floors, a food court and supermarket. It is useful on a rainy afternoon or for picking up supplies before heading into the hills. Its car park is one of the few structured parking options in central Kandy.', 7.2926, 80.6356, '7 Sri Dalada Veediya, Kandy 20000', 'https://kandycitycentre.lk/', null, null, null, 45, 'Lift access to upper floors and parking levels.', array['mall', 'rainy-day', 'food', 'parking', 'supermarket']::text[], true, 'Any time', 'Security screening at entrances.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 60),
  ('plc-central-market', 'kandy-central-market', 'Kandy Central Market', 'shopping', 'A lively municipal market for fruit, vegetables, spices and everyday local shopping.', 'Kandy''s central market is a working municipal market rather than a tourist attraction. Stalls overflow with produce, spices and household goods, and it is a good place to see the city going about its day. Expect crowds, uneven floors and early trading hours.', 7.2936, 80.635, 'Market Street, Kandy 20000', null, null, null, null, 30, 'Narrow aisles and uneven surfaces; not well suited to wheelchairs.', array['market', 'local', 'food', 'budget', 'photography']::text[], true, 'Morning', 'Bring small notes. Ask before photographing traders.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 50),
  ('plc-royal-palace', 'royal-palace-kandy', 'Royal Palace of Kandy', 'heritage', 'The former royal residence adjoining the Temple of the Tooth.', 'The Royal Palace complex once housed the kings of Kandy and now contains the Temple of the Tooth and the National Museum. The surviving halls and courtyards give a sense of the pre-colonial kingdom''s scale. Access to interiors varies with museum and temple operations.', 7.2942, 80.6414, 'Palace Square, Kandy 20000', null, null, null, null, 45, 'Historic courtyards with steps and uneven paving.', array['kingdom', 'heritage', 'unesco', 'architecture']::text[], true, 'Morning', 'Part of the complex is an active temple; dress and behaviour rules apply.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 80),
  ('plc-national-museum', 'national-museum-kandy', 'National Museum of Kandy', 'museum', 'A compact museum of Kandyan kingdom history, craft and royal objects.', 'Housed in part of the former royal palace, the National Museum of Kandy covers the kingdom''s history, crafts, and European contact. It is a useful indoor stop that pairs naturally with the Temple of the Tooth. Displays are modest but the setting is significant.', 7.2948, 80.6418, 'Palace Square, Kandy 20000', 'https://museum.gov.lk/', null, null, null, 45, 'Historic building with steps; limited step-free access.', array['museum', 'history', 'indoor', 'rainy-day', 'kingdom']::text[], true, 'Any time', 'Check current opening days before travelling; museum schedules change.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 72),
  ('plc-udawattakele', 'udawattakele-forest-reserve', 'Udawattakele Forest Reserve', 'nature', 'A forested ridge above the palace with shaded trails and birdlife.', 'Udawattakele is a protected forest reserve on the hill behind the Temple of the Tooth, historically a royal pleasure garden. Trails wind through dense canopy past reservoirs and viewpoints, with good birdwatching early in the day. Paths can be slippery after rain and are not uniformly marked.', 7.2989, 80.6422, 'Udawattakele, Kandy 20000', null, null, null, null, 90, 'Steep, uneven forest trails; not suitable for wheelchairs or strollers.', array['forest', 'birds', 'hike', 'nature', 'shade']::text[], false, 'Early morning', 'Wear shoes with grip and take water. Leech protection is sensible in the wet season.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 78),
  ('plc-botanic-gardens', 'royal-botanic-gardens-peradeniya', 'Royal Botanic Gardens, Peradeniya', 'nature', 'Sri Lanka''s best-known botanic garden, spread across a river bend west of Kandy.', 'The Royal Botanic Gardens at Peradeniya cover more than 60 hectares around the Mahaweli River, with palm avenues, an orchid collection and enormous fig trees. It is a relaxed half-day outing and a favourite local picnic spot. Allow extra time for the journey from central Kandy.', 7.2706, 80.5956, 'Peradeniya, Kandy 20400', 'https://botanicgardens.gov.lk/', null, null, null, 120, 'Main paths are paved and largely level; some lawns and side paths are not.', array['gardens', 'family', 'walk', 'photography', 'half-day']::text[], false, 'Morning, before the heat', 'About 6 km from the city centre. Bring water, sun protection and insect repellent.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 90),
  ('plc-tea-museum', 'ceylon-tea-museum', 'Ceylon Tea Museum', 'museum', 'A tea factory museum on the Hantana road explaining Sri Lanka''s tea industry.', 'The Ceylon Tea Museum occupies a former tea factory on the road up to Hantana. Exhibits cover processing machinery, tea culture and the industry''s history, with a tasting room and views over the hills. It is a good short stop on the way to the Hantana viewpoints.', 7.2818, 80.6275, 'Hantana Road, Kandy 20000', 'https://ceylonteamuseum.com/', null, null, null, 60, 'Multi-level former factory with stairs; not fully step-free.', array['tea', 'museum', 'indoor', 'rainy-day', 'hills']::text[], true, 'Late morning', 'A tuk-tuk is the simplest way up. Check current opening days before visiting.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 65),
  ('plc-viewpoint', 'rajapihilla-viewpoint', 'Rajapihilla Mawatha Viewpoint', 'viewpoint', 'A roadside terrace above the lake with a classic panorama of central Kandy.', 'The bend on Rajapihilla Mawatha is the postcard view of Kandy: the lake, the temple complex and the hills behind. It is a short ride or a steep walk from the centre, and best in late afternoon light. There is limited space and traffic on the road.', 7.2867, 80.6299, 'Rajapihilla Mawatha, Kandy 20000', null, null, null, null, 25, 'Roadside viewing area with a slope and no dedicated platform.', array['view', 'sunset', 'photography', 'free', 'lake']::text[], false, 'Late afternoon to sunset', 'Watch for traffic; there is no proper car park.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 85),
  ('plc-asgiriya', 'asgiriya-maha-vihara', 'Asgiriya Maha Vihara', 'religious', 'One of Kandy''s two historic monastic chapters, north of the city centre.', 'Asgiriya Maha Vihara is the seat of one of the two fraternities of the Siyam Nikaya that share custody of the Temple of the Tooth. The temple complex is quieter than the Dalada Maligawa and gives a sense of the monastic side of Kandy. Dress respectfully and avoid disturbing ceremonies.', 7.3003, 80.6322, 'Asgiriya, Kandy 20000', null, null, null, null, 35, 'Temple grounds with steps and uneven paving.', array['temple', 'monastery', 'quiet', 'culture']::text[], true, 'Morning', 'Active monastery; cover shoulders and knees and keep voices low.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 45),
  ('plc-malwatte', 'malwatte-maha-vihara', 'Malwatte Maha Vihara', 'religious', 'The second of Kandy''s great monastic chapters, close to the lake.', 'Malwatte Maha Vihara lies just east of Kandy Lake and is the headquarters of the Malwatte chapter. Its painted assembly hall and courtyard are architecturally rewarding and usually calm. It is an easy addition to a lake-side walk.', 7.2917, 80.6374, 'Malwatte Vihara Road, Kandy 20000', null, null, null, null, 30, 'Courtyard and hall with steps.', array['temple', 'monastery', 'architecture', 'quiet']::text[], true, 'Morning or late afternoon', 'Active monastery; dress modestly and ask before photographing monks.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 48),
  ('plc-st-pauls', 'st-pauls-church-kandy', 'St. Paul''s Church, Kandy', 'religious', 'A 19th-century Anglican church beside the Temple of the Tooth grounds.', 'St. Paul''s Church was built in the 1840s for the British garrison and congregation in Kandy. Its neo-Gothic interior and memorials offer a quiet contrast to the busy temple precinct next door. The church is still in use and may be closed outside service times.', 7.293, 80.6395, 'Cathedral Street, Kandy 20000', null, null, null, null, 20, 'Steps at the entrance; interior mostly level.', array['church', 'colonial', 'architecture', 'quiet', 'free']::text[], true, 'Daytime', 'Respect services; opening times are not consistently published.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 40),
  ('plc-garrison-cemetery', 'kandy-garrison-cemetery', 'Kandy Garrison Cemetery', 'heritage', 'A preserved colonial cemetery with shaded paths and weathered memorials.', 'The Garrison Cemetery holds the graves of British soldiers, administrators and settlers from the 19th century. It is maintained as a heritage site and is a quiet, atmospheric stop above the lake. Visits are best combined with the nearby temple and viewpoint.', 7.2965, 80.6385, 'Garrison Cemetery Road, Kandy 20000', null, null, null, null, 25, 'Uneven grass paths and steps.', array['cemetery', 'colonial', 'heritage', 'quiet', 'free']::text[], false, 'Morning', 'A donation may be requested for maintenance.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 35),
  ('plc-gadaladeniya', 'gadaladeniya-temple', 'Gadaladeniya Temple', 'heritage', 'A 14th-century stone temple with a distinctive south Indian-influenced design.', 'Gadaladeniya is one of the three ''Gampola period'' temple sites west of Kandy, built in the 14th century. Its stone shrine and painted interiors show a blend of Sinhalese and South Indian architectural traditions. It is usually visited together with Lankatilaka and Embekke.', 7.3167, 80.5917, 'Gadaladeniya, Gampola Road, Kandy District', null, null, null, null, 40, 'Stone steps and uneven ground.', array['temple', 'heritage', '14th-century', 'architecture', 'excursion']::text[], true, 'Morning', 'About 12 km west of Kandy; a vehicle is the practical option.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 58),
  ('plc-lankatilaka', 'lankatilaka-temple', 'Lankatilaka Temple', 'heritage', 'A hilltop 14th-century temple with fine stonework and views over paddy fields.', 'Lankatilaka Vihara sits on a rock outcrop near Handessa, reached by a long flight of steps. The temple is known for its carved stone entrance and seated Buddha images, and the terrace looks across the surrounding countryside. It pairs naturally with Gadaladeniya and Embekke.', 7.3244, 80.585, 'Handessa, Kandy District', null, null, null, null, 45, 'Long staircase to the temple terrace; not step-free.', array['temple', 'heritage', 'views', 'architecture', 'excursion']::text[], true, 'Morning', 'Climb is exposed; carry water and dress modestly.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 57),
  ('plc-embekke', 'embekke-devale', 'Embekke Devale', 'heritage', 'A 14th-century wooden shrine famous for its intricately carved pillars.', 'Embekke Devale is a small but remarkable timber shrine dedicated to Kataragama, with carved wooden pillars and bracket figures. It completes the classic Gampola-period circuit with Gadaladeniya and Lankatilaka. The scale is intimate and the craftsmanship is the attraction.', 7.3105, 80.5839, 'Embekke, Kandy District', null, null, null, null, 30, 'Steps and uneven ground around the shrine.', array['temple', 'woodcarving', 'heritage', 'excursion', 'architecture']::text[], true, 'Morning', 'Combine with Gadaladeniya and Lankatilaka for a half-day loop.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 52),
  ('plc-degaldoruwa', 'degaldoruwa-temple', 'Degaldoruwa Temple', 'heritage', 'A rock-cave temple known for 18th-century Kandyan murals.', 'Degaldoruwa is a cave temple north-east of Kandy, excavated into a rock outcrop in the 18th century. Its interior preserves vivid Kandyan-period paintings and a reclining Buddha. It is a worthwhile excursion for travellers interested in art and religious history.', 7.3167, 80.6167, 'Degaldoruwa, Kandy District', null, null, null, null, 35, 'Rock-cut steps and low doorways; limited accessibility.', array['cave', 'murals', 'temple', 'heritage', 'art']::text[], true, 'Morning', 'Interior may be dark; a small torch helps. Remove shoes before entering.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 47),
  ('plc-cultural-show', 'kandy-cultural-dance-show', 'Kandyan Cultural Dance Show', 'experience', 'An evening performance of Kandyan dance, drumming and fire-walking.', 'Several venues around Kandy stage nightly cultural shows combining Kandyan dance, drumming, acrobatics and fire-walking. The performances are aimed at visitors and last about an hour. Book through your accommodation or at the venue; quality and availability vary by season.', 7.2886, 80.6375, 'Kandy Lake Club area, Kandy 20000', null, null, null, null, 70, 'Venue-dependent; ask about step-free seating when booking.', array['dance', 'performance', 'evening', 'culture', 'family']::text[], true, 'Evening', 'Schedule and ticket prices vary by venue and season; confirm locally.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', true, 74),
  ('plc-hantana', 'hantana-viewpoint', 'Hantana Hills Viewpoint', 'viewpoint', 'A hill road above Kandy with tea gardens and wide valley views.', 'The Hantana road climbs west of the city through tea smallholdings and forest patches. Viewpoints along the way look over Kandy and towards the Knuckles range, and the air is noticeably cooler. It is best done by tuk-tuk or vehicle with a stop at the tea museum.', 7.274, 80.625, 'Hantana, Kandy 20000', null, null, null, null, 50, 'Roadside stops with uneven ground; not a formal accessible site.', array['view', 'tea', 'hills', 'sunset', 'drive']::text[], false, 'Late afternoon', 'Narrow road with bends; agree a return trip with your driver.', 'unverified', 'KandyVerse editorial seed', null, null, 'district', false, 62),
  ('plc-peradeniya-junction', 'peradeniya-junction', 'Peradeniya Junction', 'transport', 'A major rail junction west of Kandy serving the hill-country and Colombo lines.', 'Peradeniya Junction is where the Colombo–Kandy line meets the branch towards the hill country. Some trains stop here rather than at Kandy station, and it is the closest rail access to the Botanic Gardens. Allow time for the road transfer into Kandy.', 7.2588, 80.5968, 'Peradeniya, Kandy District', null, null, null, null, 15, 'Footbridges and steps between platforms.', array['train', 'junction', 'transport', 'gardens']::text[], true, 'Daytime', 'Check whether your service stops at Peradeniya or Kandy before buying a ticket.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 42),
  ('plc-bus-stand', 'kandy-bus-stand', 'Kandy Central Bus Stand', 'transport', 'The city''s main bus terminal for regional and long-distance services.', 'Kandy''s central bus stand sits beside the railway station and clock tower, with services across the Central Province and to Colombo. Buses are frequent and cheap but crowded at peak times. Keep bags close and confirm the destination with the conductor.', 7.294, 80.6332, 'Station Road, Kandy 20000', null, null, null, null, 15, 'Busy, uneven terminal with limited accessibility.', array['bus', 'transport', 'budget', 'regional']::text[], false, 'Daytime', 'Allow extra time during morning and evening peaks.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 38),
  ('plc-hospital', 'kandy-general-hospital', 'Teaching Hospital Kandy', 'health', 'The main public hospital for Kandy and the surrounding district.', 'The Teaching Hospital Kandy is the district''s principal public medical facility, located just south of the city centre. Emergency and outpatient services operate here, though waits can be long. Travel insurance details and payment arrangements should be confirmed on arrival.', 7.2896, 80.6315, 'Hospital Road, Kandy 20000', null, null, null, null, 30, 'Hospital buildings vary; ask staff for accessible routes.', array['hospital', 'emergency', 'health', 'public']::text[], true, 'Emergency: any time', 'For emergencies call Sri Lanka''s emergency line 1990 (ambulance) or 119 (police).', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 30),
  ('plc-pharmacy', 'union-chemists-kandy', 'Union Chemists', 'health', 'A long-standing pharmacy in the commercial centre near Dalada Veediya.', 'Union Chemists is a central pharmacy convenient for travellers needing basic medicines and supplies. Opening hours are not consistently published and may change on public holidays. For anything serious, go to the Teaching Hospital Kandy.', 7.2927, 80.6368, 'Dalada Veediya, Kandy 20000', null, null, null, null, 10, 'Street-level shop with a step at the entrance.', array['pharmacy', 'medicine', 'health', 'city-centre']::text[], true, 'Daytime', 'Carry prescriptions in original packaging. Confirm opening hours locally.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 26),
  ('plc-atm', 'commercial-bank-atm-dalada-veediya', 'Commercial Bank ATM — Dalada Veediya', 'services', 'A central ATM on the main road between the clock tower and the temple.', 'This ATM is on the Dalada Veediya commercial strip, within walking distance of the lake, temple and station. International cards are commonly accepted, but availability and fees vary by issuer. Withdraw inside daylight hours where possible.', 7.2925, 80.6376, 'Dalada Veediya, Kandy 20000', null, null, null, null, 5, 'Street-level access.', array['atm', 'cash', 'bank', 'services']::text[], false, 'Daytime', 'Carry a backup card and small cash. Report retained cards to the bank.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 20),
  ('plc-parking', 'kandy-city-centre-car-park', 'Kandy City Centre Car Park', 'services', 'Structured multi-storey parking in the middle of the city.', 'The Kandy City Centre car park is one of the few structured parking options in the congested centre. It is useful if you are driving yourself, though entrances and exits can queue at peak times. Rates and hours are set by the operator.', 7.2928, 80.6353, 'Kandy City Centre, Kandy 20000', 'https://kandycitycentre.lk/', null, null, null, 5, 'Lift access between parking and retail levels.', array['parking', 'car', 'city-centre', 'services']::text[], true, 'Early', 'Central Kandy traffic is heavy; parking fills quickly on weekends.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 18),
  ('plc-toilets', 'public-toilets-kandy-lake', 'Public Toilets — Kandy Lake', 'services', 'Public washroom facilities near the lake walk.', 'Public toilet facilities are available near the lake and central car parks, typically for a small fee. Cleanliness and opening hours vary. Carry tissue and hand sanitiser as a precaution.', 7.292, 80.6398, 'Kandy Lake, Kandy 20000', null, null, null, null, 5, 'Basic facilities; accessibility is limited.', array['toilets', 'washroom', 'services', 'lake']::text[], true, 'Daytime', 'Small fee may apply. Carry your own tissue and sanitiser.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 15),
  ('plc-queens-hotel', 'queens-hotel-kandy', 'The Queen''s Hotel', 'hotel', 'A colonial-era hotel facing the lake in the centre of Kandy.', 'The Queen''s Hotel occupies a long colonial building on the lake side of the city centre, within walking distance of the Temple of the Tooth and the station. Its public veranda and restaurant are part of Kandy''s hotel history. Room availability and rates should be checked directly.', 7.2937, 80.635, '4 Dalada Veediya, Kandy 20000', null, null, null, null, 15, 'Historic building; ask the hotel about step-free rooms and lift access.', array['hotel', 'colonial', 'central', 'stay']::text[], true, 'Any time', 'Book directly and confirm current rates; listings change frequently.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 32),
  ('plc-empire-cafe', 'the-empire-cafe', 'The Empire Café', 'food', 'A central café on Temple Street serving breakfast, coffee and light meals.', 'The Empire Café is a convenient stop near the temple precinct for coffee, breakfast and simple meals. It is popular with visitors for its central location and outdoor seating. Menu, hours and prices should be confirmed on site.', 7.2924, 80.6383, '21 Temple Street, Kandy 20000', null, null, null, null, 45, 'Street-level with a small step; seating is partly outdoors.', array['cafe', 'breakfast', 'coffee', 'central', 'budget']::text[], true, 'Breakfast or lunch', 'Prices and opening hours are not verified; check locally.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 44),
  ('plc-white-house', 'white-house-restaurant-kandy', 'White House Restaurant & Lounge', 'food', 'A long-running restaurant on Dalada Veediya serving Sri Lankan and Western dishes.', 'White House is a well-established restaurant in the commercial centre, a short walk from the lake and temple. The menu covers Sri Lankan rice and curry as well as Western dishes, making it an easy choice for mixed groups. Confirm current hours and prices on site.', 7.2929, 80.6382, '21 Dalada Veediya, Kandy 20000', null, null, null, null, 60, 'Street-level entrance; interior seating on one level.', array['restaurant', 'rice-and-curry', 'central', 'family']::text[], true, 'Lunch or dinner', 'Menu and prices are not verified; check locally.', 'unverified', 'KandyVerse editorial seed', null, null, 'approximate', false, 43),
  ('plc-kandyan-food', 'kandyan-home-cooking-experience', 'Kandyan Home Cooking Experience', 'experience', 'A hosted introduction to Kandyan home cooking and market ingredients.', 'Several local hosts in and around Kandy run small home-cooking sessions covering rice and curry, hoppers and Kandyan-specific dishes. These are typically booked in advance and include a market visit or a shared meal. KandyVerse lists this as a category of experience, not a specific verified operator — choose providers with recent, independent reviews.', 7.2915, 80.639, 'Kandy area (operator-dependent)', null, null, null, null, 150, 'Varies by host; confirm directly.', array['food', 'cooking', 'local', 'experience', 'indoor']::text[], true, 'Lunch or dinner', 'This is a category entry, not a booking. Verify the operator, price and cancellation terms before paying.', 'unverified', 'KandyVerse editorial seed', null, null, 'district', false, 36)
